// Pattern: Break problem into smaller subproblems
// Frontend equivalent: Component tree rendering

// Anatomy of recursion:
// 1. Base case (stop condition)
// 2. Recursive case (smaller problem)
// 3. Combine results

const factorial = (n) => {
  // Base case
  if (n <= 1) return 1;

  // Recursive case
  return n * factorial(n - 1);
};

