        setProduct(prev => ({ ...prev, price: data.newPrice }));
      }

      if (data.type === 'STOCK_UPDATE') {
        setProduct(prev => ({ ...prev, stock: data.remaining }));
      }

      if (data.type === 'SALE_END') {
        setTimeLeft(null);
      }
    };

    return () => ws.close();
  }, [productId]);

  return (
